const WHO_NEWS=[["30 Oct 2026", "Barbados eliminates mother-to-child transmission of HIV", "https://www.who.int/news/item/30-10-2026-barbados-eliminates-mother-to-child-transmission-of-hiv"], ["23 Oct 2026", "WHO and ENHYPEN join efforts to inspire young blood donors globally", "https://www.who.int/news/item/23-10-2026-who-and-enhypen-join-efforts-to-inspire-young-blood-donors-globally"], ["21 Oct 2026", "New global framework launched to track increasing health risks of extreme heat for pregnant women, newborns and children", "https://www.who.int/news/item/21-10-2026-new-global-framework-launched-to-track-increasing-health-risks-of-extreme-heat-for-pregnant-women--newborns-and-children"], ["16 Oct 2026", "INTERPOL and WHO sign agreement to strengthen global health and security protection", "https://www.who.int/news/item/16-10-2026-interpol-and-who-sign-agreement-to-strengthen-global-health-and-security-protection"], ["12 Oct 2026", "WHO welcomes adoption of United Nations political declaration on pandemic prevention, preparedness and response", "https://www.who.int/news/item/12-10-2026-who-welcomes-adoption-of-united-nations-political-declaration-on-pandemic-prevention-preparedness-and-response"], ["12 Oct 2026", "WHO Pandemic Hub sets ambitious goal to detect new outbreaks within 24 hours", "https://www.who.int/news/item/12-10-2026-who-pandemic-hub-sets-ambitious-goal-to-detect-new-outbreaks-within-24-hours"], ["9 Oct 2026", "WHO urges shift from institutional to community-based mental health care", "https://www.who.int/news/item/09-10-2026-who-urges-shift-from-institutional-to-community-based-mental-health-care"], ["8 Oct 2026", "New global roadmap launched to tackle hypertension in pregnancy, a leading cause of maternal and newborn deaths", "https://www.who.int/news/item/08-10-2026-new-global-roadmap-launched-to-tackle-hypertension-in-pregnancy-a-leading-cause-of-maternal-and-newborn-deaths"], ["7 Oct 2026", "WHO issues first global guidelines on child and adolescent obesity", "https://www.who.int/news/item/07-10-2026-who-issues-first-global-guidelines-on-child-and-adolescent-obesity"], ["30 Sep 2026", "WHO releases new guidance to prevent heat-related illness at mass gatherings", "https://www.who.int/news/item/30-09-2026-who-releases-new-guidance-to-prevent-heat-related-illness-at-mass-gatherings"]];
function ticker(){
 const items=WHO_NEWS.map(n=>`<a href="${n[2]}" target="_blank" rel="noopener"><time>${n[0]}</time>${esc(n[1])}</a><span class="tk-sep" aria-hidden="true">◆</span>`).join('');
 return`<div class="ticker" role="region" aria-label="WHO news"><div class="wrapx tk-in"><a class="tk-lab" href="https://www.who.int/news" target="_blank" rel="noopener"><span class="tk-dot" aria-hidden="true"></span>${t('WHO News')}</a><div class="tk-view"><div class="tk-track">${items}<span class="tk-dup" aria-hidden="true">${items}</span></div></div><span class="tk-note">${t('Updated')} 2 Nov 2026</span></div></div>`;
}
