function consultModal(){
 const i=S.cdoc||0,d=DOCS[i%DOCS.length],me=persona();
 return`<div class="scrim" data-a="close"></div><div class="modal cwin" role="dialog" aria-label="Video consultation">
 <div class="cw-head"><div style="min-width:0"><b>Video consultation</b><span class="small muted"> · ${esc(d.name)} · ${d.spec}</span></div><span class="pill ok">● Live <span id="ctimer" class="mono">00:00</span></span><button class="x" data-a="close" aria-label="Close">×</button></div>
 <div class="cw-body">
  <div class="cw-video"><div class="cw-doc">${docAvatar(i,170)}<span class="cw-name">${esc(d.name)}</span>${S.mute?'<span class="cw-muted">You are muted</span>':''}</div>
   <div class="cw-self"><span>${me.name.split(' ').map(w=>w[0]).join('').slice(0,2)}</span><small>Your camera is off</small></div>
   <div class="cw-ctrl"><button class="cbtn" data-a="c-mute" aria-pressed="${!!S.mute}">${S.mute?'Unmute':'Mute'}</button><button class="cbtn" data-a="c-vitals">Share vitals</button><button class="cbtn" data-a="c-phr">Share health record</button><button class="cbtn end" data-a="c-end">End call</button></div></div>
  <div class="cw-chat"><div class="cw-pt"><b>${esc(me.name)}</b> <span class="small muted">· ${me.card.type} ${me.card.no}</span></div><div class="cw-msgs" id="cmsgs">${(S.chat||[]).map(m=>`<div class="msg ${m.me?'me':''}"><b>${m.me?'You':esc(d.name)}</b><p>${esc(m.t)}</p><time>${m.at}</time></div>`).join('')}${S.typing?`<div class="msg typing"><b>${esc(d.name)}</b><p>typing…</p></div>`:''}</div>
   <div class="cw-send"><input class="inp" id="cmsg" placeholder="Type a message to the doctor" aria-label="Message"><button class="btn pri sm" data-a="c-send">Send</button></div></div>
 </div><p class="small muted" style="margin:0">Demo consultation. No real call is placed.</p></div>`;
}
