function cmBox(){
 if(!P.india)return'';
 if(!P.st)return`<section class="sbox"><div class="sbh"><span class="eyebrow">${t('Chief Minister')}</span></div><p class="small muted">Choose a state from the State dropdown at the top to see its Chief Minister.</p></section>`;
 const n=CM[P.st];
 if(!n)return`<section class="sbox"><div class="sbh"><span class="eyebrow">${t('Chief Minister')}</span><span class="flagc">${esc(P.st)}</span></div><p class="small muted">${esc(P.st)} is a union territory without a Chief Minister. It is run by its Lieutenant Governor or Administrator.</p></section>`;
 const ph=cmPhoto(P.st),ini=n.split(/\s+/).filter(w=>/^[A-Z]/.test(w)&&!/\.$/.test(w)).slice(0,2).map(w=>w[0]).join('');
 const yt='https://www.youtube.com/results?search_query='+encodeURIComponent(n+' '+P.st+' CM live');
 return`<section class="sbox lead cm"><div class="sbh"><span class="eyebrow">${t('Chief Minister')}</span><span class="flagc">${esc(P.st)}</span></div>
  <div class="cmrow"><div class="cmph">${ph?`<img src="${ph}" alt="${esc(n)}">`:`<span class="avatar" aria-hidden="true">${ini}</span>`}</div><div style="min-width:0"><p class="muted small">${LANG==='en'?'Chief Minister of '+esc(P.st):t('Chief Minister')+' · '+esc(P.st)}</p><h3 style="font-size:19px">${esc(n)}</h3></div></div>
  <a class="btn live" href="${yt}" target="_blank" rel="noopener"><span class="live-dot" aria-hidden="true"></span>${t('Join Live')}</a></section>`;
}
