const JOBS=()=>{const A=i=>P.areas[i%P.areas.length];return[
 ['Health Advisor (BPO call centre)',A(0),'Full-time · shifts',Math.max(3,Math.round(42*Math.min(4,Math.max(.2,P.scale))))],
 ['Clinical Analyst (KPO, staff nurse)',A(1),'Full-time',Math.max(2,Math.round(12*Math.min(4,Math.max(.2,P.scale))))],
 ['FHIR Integration Engineer','Remote / '+A(0),'Contract · 12 months',4],
 [(P.india?'ASHA':'Community Health Worker')+' Coordinator',A(2),'Full-time',Math.max(2,Math.round(18*Math.min(4,Math.max(.2,P.scale))))],
 ['Command Centre Duty Officer',A(0),'24×7 rota',6]]};
function sideBoxes(){
 const h=HOG[P.cc]||['Head of government','—'];
 const ini=h[1].split(/\s+/).filter(w=>/^[A-ZÀ-Ý]/.test(w)).slice(0,2).map(w=>w[0]).join('');
 const docs=DOCS.slice(0,3),st=['Available now','In OPD till 5 pm','Tele-consult from 6 pm'],sc=['ok','info','warn'];
 const q=encodeURIComponent(P.co.n+' health');
 const notes=[[ago(5),`${Math.max(2,Math.round(14*Math.min(3,Math.max(.3,P.scale))))} new labs connected in ${P.place} this week`],[ago(30),`${P.pr.id} linking now live at all ${P.india?'district hospitals':'public hospitals'} in ${P.areas[0]}`],[ago(76),`Red-flag first-call time in ${P.place} down to 27 minutes`]];
 const ph=pmPhoto(),yt='https://www.youtube.com/results?search_query='+encodeURIComponent(h[1]+' live'),sd=SIDE_DOCS(),d0=DOCS[sd[0]];
 return`<section class="sbox lead"><div class="sbh"><span class="eyebrow">${t('Leadership')}</span><span class="flagc">${flagE(P.cc)} ${P.co.n}</span></div>
  <div class="leadph">${ph?`<img src="${ph}" alt="${esc(h[1])}">`:`<div class="ph-empty"><span class="avatar xl" aria-hidden="true">${ini||'—'}</span><label class="btn sm" for="pmphoto">Add official photo</label></div>`}<input type="file" id="pmphoto" accept="image/*" hidden></div>
  <div><p class="muted small">${LANG==='en'?h[0]+' of '+P.co.n:t(h[0])+' · '+P.co.n}</p><h3 style="font-size:19px">${esc(h[1])}</h3></div>
  <a class="btn live" href="${yt}" target="_blank" rel="noopener"><span class="live-dot" aria-hidden="true"></span>${t('Join Live')}</a>
  
  </section>
${cmBox()}
 <section class="sbox"><div class="sbh"><span class="eyebrow">${t('Doctor on duty')}</span><span class="pill ok">● ${t('Online')}</span></div>
  <div class="dfeat">${docAvatar(sd[0],84)}<div style="min-width:0"><h3>${esc(d0.name)}</h3><div class="small muted">${d0.spec}</div><div class="small muted">${esc(d0.org)}</div><div class="small" style="margin-top:4px"><b>Wait:</b> about 3 min · <b>Queue:</b> 2</div></div></div>
  <button class="btn pri" data-a="consult-open" data-i="${sd[0]}">▶ ${t('Join doctor consultation')}</button>
  ${sd.slice(1).map(k=>{const d=DOCS[k];return`<div class="drow">${docAvatar(k,44)}<div style="min-width:0;flex:1"><b>${esc(d.name)}</b><div class="small muted">${d.spec}</div></div><button class="btn sm" data-a="consult-open" data-i="${k}">${t('Join')}</button></div>`}).join('')}
 </section>
 <section class="sbox"><div class="sbh"><span class="eyebrow">${t('Careers')}</span><span class="pill">${JOBS().reduce((a,j)=>a+j[3],0)} ${t('openings')}</span></div>
  ${JOBS().map((j,i)=>`<div class="jrow"><div style="min-width:0"><b>${j[0]}</b><div class="small muted">${esc(j[1])} · ${j[2]}</div></div><button class="btn sm" data-a="apply" data-i="${i}">${t('Apply')}</button></div>`).join('')}
  </section>
 <section class="sbox"><div class="sbh"><span class="eyebrow">${t('News')}</span><span class="flagc">${flagE(P.cc)} ${P.co.n}</span></div>
  <div class="feed">${notes.map(n=>`<div><time>${fmtD(n[0])}</time><span><b>Bharat HIE update</b> · ${esc(n[1])}</span></div>`).join('')}</div>
  <a class="btn sm" href="https://news.google.com/search?q=${q}" target="_blank" rel="noopener">Latest health news from ${P.co.n} ↗</a>
  <a class="small" href="https://www.who.int/news" target="_blank" rel="noopener">WHO news ↗</a>
  <p class="small muted">Live news opens on the news site in a new tab.</p></section>`;
}
function applyModal(){
 const j=JOBS()[S.job||0];
 return`<div class="scrim" data-a="close"></div><div class="modal" role="dialog" aria-label="Apply"><div class="row" style="justify-content:space-between"><div><h2>Apply: ${j[0]}</h2><p class="muted small">${esc(j[1])} · ${j[2]}</p></div><button class="x" data-a="close" aria-label="Close">×</button></div>
 <div class="grid2"><label class="fld">Full name<input class="inp" id="ap-name" value="${esc(P.nm('F',4))}"></label><label class="fld">Mobile<input class="inp" id="ap-mob" inputmode="numeric" value="9823014567"></label></div>
 <div class="grid2"><label class="fld">Qualification<select class="inp" id="ap-q"><option>Graduate</option><option>B.Sc Nursing / GNM</option><option>MBBS</option><option>B.E. / B.Tech</option><option>Other</option></select></label><label class="fld">Experience (years)<input class="inp" type="number" id="ap-exp" value="3"></label></div>
 <label class="fld">Why this role?<textarea class="inp" id="ap-why" rows="3">I want to help citizens in ${esc(P.place)} get timely care.</textarea></label>
 <button class="btn pri" data-a="ap-send">Submit application</button><p class="note">Demo form. Nothing is sent anywhere.</p></div>`;
}

